/* The benchmark pages' views, drawn from window.STRATA_BENCH
 * (assets/bench-data.js, generated by scripts/bench_data.py from the
 * committed results). Every view is a data-* attribute on an element:
 *
 *   data-rank="cloud-1m"        engines by summed places, lowest first
 *   data-places="cloud-1m"      every engine's place on every query kind
 *   data-explorer="cloud-1m"    one kind and one measure, engines sorted
 *   data-pick="cloud-1m"        a few engines and kinds as a table
 *                               (data-engines, data-kinds, data-metric)
 *   data-scoreboard             Strata's place per kind in each report
 *   data-writes="cloud-1m"      writes, freshness and streams
 *   data-load="cloud-1m"        load time and index size
 *   data-graph-rank             the graph comparison's places
 *   data-ab="bm25-load"         a before/after table
 *   data-num="cloud-1m:p50:strata:bm25" one number, inline
 *   data-overall="cloud-1m"     Strata's overall place (data-mode="tile" or "line")
 *   data-variants="cloud-1m"    the ranking under other rules
 *   data-rank-mini="cloud-10m"  the top few by summed places, and Strata (data-top)
 *   data-engine-names="a,b"     the engines the reports measured (data-also adds names)
 */
(function () {
  "use strict";
  var B = window.STRATA_BENCH;
  if (!B) return;
  var R = B.reports || {};

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; });
  }
  function fmt(v, digits) {
    if (v == null) return "–";
    if (digits != null) return v.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
    var a = Math.abs(v);
    if (a >= 1000) return Math.round(v).toLocaleString("en-US");
    if (a >= 100) return String(Math.round(v));
    if (a >= 1) return v.toPrecision(3).replace(/\.?0+$/, function (z) { return z.indexOf(".") === 0 && z.length > 1 ? "" : z; });
    return String(Number(v.toPrecision(3)));
  }
  var METRICS = {
    p50: { name: "Median latency", short: "p50", unit: "ms", lower: true, sub: "at 1 client" },
    p99: { name: "99th percentile", short: "p99", unit: "ms", lower: true, sub: "at 1 client" },
    qps4: { name: "Queries a second", short: "q/s at 4", unit: "q/s", lower: false, sub: "at 4 clients" },
    qps16: { name: "Queries a second", short: "q/s at 16", unit: "q/s", lower: false, sub: "at 16 clients" },
    recall: { name: "Recall@10", short: "recall", unit: "", lower: false, sub: "against an exact search", digits: 3 },
    ndcg: { name: "nDCG@10", short: "nDCG", unit: "", lower: false, sub: "against the collection's judgments", digits: 3 }
  };
  function ord(n) { var s = ["th", "st", "nd", "rd"], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); }
  function engineName(rep, id) {
    for (var i = 0; i < rep.engines.length; i++) if (rep.engines[i].id === id) return rep.engines[i].name;
    return id;
  }
  function kindName(rep, id) {
    for (var i = 0; i < rep.kinds.length; i++) if (rep.kinds[i].id === id) return rep.kinds[i].name;
    return id;
  }
  function val(rep, metric, e, k) {
    var m = rep.m[metric];
    return m && m[e] && m[e][k] != null ? m[e][k] : null;
  }
  /* Places of the given engines on one kind and measure; null where an
     engine has no value. */
  function placesOf(rep, metric, k, engines) {
    var lower = METRICS[metric].lower, vals = {}, out = {};
    engines.forEach(function (e) { var v = val(rep, metric, e, k); if (v != null) vals[e] = v; });
    engines.forEach(function (e) {
      if (vals[e] == null) { out[e] = null; return; }
      var p = 1;
      for (var o in vals) if (lower ? vals[o] < vals[e] : vals[o] > vals[e]) p++;
      out[e] = p;
    });
    return out;
  }
  function placeClass(p, n) {
    if (p == null) return "pl-na";
    if (p === 1) return "pl-1";
    var f = (p - 1) / Math.max(n - 1, 1);
    if (f <= 0.25) return "pl-2";
    if (f <= 0.6) return "pl-3";
    if (f < 1) return "pl-4";
    return "pl-5";
  }
  function srcLink(rep, label) {
    if (!rep || !rep.source) return "";
    return '<a href="' + esc(rep.source) + '">' + esc(label || "raw results") + "</a>" + (rep.branch ? ' <span class="muted">(branch ' + esc(rep.branch.replace("origin/", "")) + ", not yet merged)</span>" : "");
  }
  function chips(name, items, current) {
    return '<div class="filters" role="group" aria-label="' + esc(name) + '"><span class="label">' + esc(name) + "</span>" +
      items.map(function (it) {
        return '<button type="button" class="chipbtn" data-v="' + esc(it[0]) + '" aria-pressed="' + (it[0] === current) + '">' + esc(it[1]) + "</button>";
      }).join("") + "</div>";
  }

  /* -------------------------------------------------------------- rank */
  function renderRank(el) {
    var rep = R[el.getAttribute("data-rank")];
    if (!rep) return pending(el);
    var max = rep.rank[rep.rank.length - 1].points, best = rep.rank[0].points;
    var n = rep.ranked.length;
    var h = '<div class="rankbars" role="table" aria-label="Engines by summed places, fewest points first">';
    h += '<div class="rb-row rb-head" role="row"><span role="columnheader" class="rb-pl">#</span><span role="columnheader">engine</span><span role="columnheader">points, fewer is better</span><span role="columnheader" class="rb-own">top half on</span><span role="columnheader" class="rb-own">average place where it ran</span></div>';
    rep.rank.forEach(function (r, i) {
      var self = r.e === "strata";
      var w = Math.max(4, (r.points / max) * 100);
      h += '<div class="rb-row' + (self ? " self" : "") + '" role="row"><span class="rb-pl" role="cell">' + (i + 1) + '</span><span class="rb-name" role="cell">' + esc(engineName(rep, r.e)) + '</span><span class="rb-bar" role="cell"><i style="width:' + w.toFixed(1) + '%"></i><b>' + r.points + '</b></span><span class="rb-own" role="cell">' + r.half + ' <span class="muted">of ' + rep.tests + '</span></span><span class="rb-own" role="cell">' + fmt(r.own, 2) + (r.cant ? ' <span class="muted">on ' + r.ran + " tests; no result on " + r.cant + (r.cant === 1 ? " kind" : " kinds") + "</span>" : ' <span class="muted">on all ' + rep.tests + "</span>") + "</span></div>";
    });
    h += "</div>";
    h += '<p class="small muted">' + rep.tests + " tests: 14 kinds at three measures, plus recall on the vector kinds" + (rep.passes_note ? ", " + rep.passes_note : rep.passes > 1 ? ", medians of " + rep.passes + " passes" : ", one pass") + ". Places add up, so fewer points is better (" + best + " is the best here); a kind an engine cannot run counts as last (" + n + "). <a href=\"bench-method.html#ranking\">How the ranking works</a>. " + srcLink(rep) + "</p>";
    el.innerHTML = h;
  }

  /* ------------------------------------------------------------ places */
  function renderPlaces(el) {
    var rep = R[el.getAttribute("data-places")];
    if (!rep) return pending(el);
    var metric = el.getAttribute("data-metric") || "p50";
    var engines = rep.rank.map(function (r) { return r.e; });
    function draw() {
      var n = engines.length;
      var h = chips("Measure", [["p50", "Median, 1 client"], ["p99", "p99, 1 client"], ["qps4", "q/s, 4 clients"], ["qps16", "q/s, 16 clients"]], metric);
      h += '<div class="places-wrap"><table class="places"><thead><tr><th scope="col" class="k">kind</th>';
      engines.forEach(function (e) { h += '<th scope="col"' + (e === "strata" ? ' class="self"' : "") + "><span>" + esc(engineName(rep, e)) + "</span></th>"; });
      h += "</tr></thead><tbody>";
      var fam = null;
      rep.kinds.forEach(function (k) {
        if (k.fam !== fam) {
          fam = k.fam;
          h += '<tr class="grp"><th colspan="' + (n + 1) + '">' + ({ text: "Full text", cols: "Columns and keys", vec: "Vectors", hyb: "Hybrid" })[fam] + "</th></tr>";
        }
        var pl = placesOf(rep, metric, k.id, engines);
        h += '<tr><th scope="row" class="k">' + esc(k.name) + "</th>";
        engines.forEach(function (e) {
          var p = pl[e], v = val(rep, metric, e, k.id);
          var why = rep.na[e] && rep.na[e][k.id];
          var tip = "<b>" + esc(engineName(rep, e)) + "</b> · " + esc(k.name) + "<br>" + (p == null ? (why ? "Cannot run it: " + esc(why) : "No value") : ord(p) + " of " + n + ": " + esc(fmt(v)) + " " + esc(METRICS[metric].unit));
          h += '<td class="' + placeClass(p, n) + (e === "strata" ? " self" : "") + '"><span tabindex="0" data-tip="' + esc(tip) + '">' + (p == null ? "–" : p) + "</span></td>";
        });
        h += "</tr>";
      });
      h += "</tbody></table></div>";
      h += '<div class="legend pl-legend"><span><i class="pl-1"></i>1st</span><span><i class="pl-2"></i>top quarter</span><span><i class="pl-3"></i>middle</span><span><i class="pl-4"></i>lower</span><span><i class="pl-5"></i>last</span><span><i class="pl-na"></i>no result</span><span>Columns in ranking order. Hover or tap a cell for its value.</span></div>';
      el.innerHTML = h;
      el.querySelectorAll(".chipbtn").forEach(function (b) { b.addEventListener("click", function () { metric = b.getAttribute("data-v"); draw(); }); });
    }
    draw();
  }

  /* ---------------------------------------------------------- explorer */
  function renderExplorer(el) {
    var rep = R[el.getAttribute("data-explorer")];
    if (!rep) return pending(el);
    var kind = el.getAttribute("data-kind") || "bm25";
    var metric = el.getAttribute("data-metric") || "p50";
    var engines = rep.engines.map(function (e) { return e.id; });
    var hasRecall = !!rep.m.recall, hasNdcg = !!rep.m.ndcg;
    function draw() {
      var isRecallKind = ["vector", "vector + filter", "similar items"].indexOf(kind) >= 0;
      if (metric === "recall" && !isRecallKind) metric = "p50";
      var M = METRICS[metric];
      var h = '<div class="bx-controls">';
      h += chips("Kind", rep.kinds.map(function (k) { return [k.id, k.name]; }), kind);
      var ms = [["p50", "Median, 1 client"], ["p99", "p99, 1 client"], ["qps4", "q/s, 4 clients"], ["qps16", "q/s, 16 clients"]];
      if (hasRecall && isRecallKind) ms.push(["recall", "Recall@10"]);
      if (hasNdcg) ms.push(["ndcg", "nDCG@10"]);
      h += chips("Measure", ms, metric);
      h += "</div>";
      var rows = [], missing = [];
      engines.forEach(function (e) {
        var v = val(rep, metric, e, kind);
        if (v == null) missing.push(e); else rows.push({ e: e, v: v });
      });
      rows.sort(function (a, b) { return M.lower ? a.v - b.v : b.v - a.v; });
      var max = rows.length ? Math.max.apply(null, rows.map(function (r) { return r.v; })) : 1;
      var log = (metric === "p50" || metric === "p99") && rows.length && max / Math.max(rows[0].v, 1e-9) > 30;
      var lo = rows.length ? Math.min.apply(null, rows.map(function (r) { return r.v; })) : 1;
      h += '<div class="bx-title"><b>' + esc(kindName(rep, kind)) + "</b> · " + esc(M.name) + " " + esc(M.sub) + (M.unit ? ", " + esc(M.unit) : "") + (M.lower ? ", lower is better" : ", higher is better") + (log ? " · log scale" : "") + "</div>";
      h += '<ol class="bx-bars">';
      var pos = 0;
      rows.forEach(function (r) {
        var off = rep.ranked.indexOf(r.e) < 0;
        if (!off) pos++;
        var pct = log ? (Math.log(r.v) - Math.log(lo / 2)) / (Math.log(max) - Math.log(lo / 2)) : r.v / max;
        pct = Math.max(0.015, Math.min(1, pct)) * 100;
        var note = rep.notes[r.e] && rep.notes[r.e][kind];
        var rec = metric !== "recall" && isRecallKind ? val(rep, "recall", r.e, kind) : null;
        var eng = rep.engines.filter(function (x) { return x.id === r.e; })[0];
        h += '<li class="' + (r.e === "strata" ? "self" : off ? "off" : "") + '"><span class="bx-pl">' + (off ? "–" : pos) + '</span><span class="bx-name">' + esc(eng.name) + (eng.lane ? "<small>" + esc(eng.lane) + "</small>" : eng.ver ? "<small>" + esc(eng.ver) + "</small>" : "") + '</span><span class="bx-bar"><i style="width:' + pct.toFixed(1) + '%"></i></span><span class="bx-v">' + esc(fmt(r.v, M.digits)) + (M.unit && M.unit !== "q/s" ? " " + esc(M.unit) : "") + (rec != null ? '<small>recall ' + fmt(rec, 3) + "</small>" : "") + (note ? '<small class="star" data-tip="' + esc(note) + '" tabindex="0">trial licence</small>' : "") + "</span></li>";
      });
      h += "</ol>";
      if (missing.length) {
        h += '<div class="bx-na"><b>No result' + (metric === "recall" ? " or no recall" : "") + ":</b> " + missing.map(function (e) {
          var why = rep.na[e] && rep.na[e][kind];
          return '<span tabindex="0" data-tip="' + esc(why || "no value for this measure") + '">' + esc(engineName(rep, e)) + "</span>";
        }).join(", ") + "</div>";
      }
      el.innerHTML = h;
      el.querySelectorAll(".filters").forEach(function (f, i) {
        f.querySelectorAll(".chipbtn").forEach(function (b) {
          b.addEventListener("click", function () { if (i === 0) kind = b.getAttribute("data-v"); else metric = b.getAttribute("data-v"); draw(); });
        });
      });
    }
    draw();
  }

  /* -------------------------------------------------------------- pick */
  function renderPick(el) {
    var rep = R[el.getAttribute("data-pick")];
    if (!rep) return pending(el);
    var metric = el.getAttribute("data-metric") || "p50";
    var M = METRICS[metric];
    var engines = (el.getAttribute("data-engines") || "strata,es,os").split(",");
    var kinds = (el.getAttribute("data-kinds") || "bm25,vector").split("|");
    var title = el.getAttribute("data-title");
    var h = (title ? '<div class="bx-title"><b>' + esc(title) + "</b></div>" : "") + '<div class="table-wrap"><table class="data pick"><thead><tr><th scope="col">kind</th>';
    engines.forEach(function (e) { h += '<th scope="col"' + (e === "strata" ? ' class="self"' : "") + ">" + esc(engineName(rep, e)) + "</th>"; });
    h += "</tr></thead><tbody>";
    kinds.forEach(function (k) {
      var vs = engines.map(function (e) { return val(rep, metric, e, k); });
      var have = vs.filter(function (v) { return v != null; });
      var best = have.length ? (M.lower ? Math.min.apply(null, have) : Math.max.apply(null, have)) : null;
      h += '<tr><th scope="row">' + esc(kindName(rep, k)) + "</th>";
      vs.forEach(function (v, i) {
        var e = engines[i];
        var rec = (metric === "p50" || metric === "qps4") && ["vector", "vector + filter", "similar items"].indexOf(k) >= 0 ? val(rep, "recall", e, k) : null;
        h += '<td class="n' + (e === "strata" ? " self" : "") + '">' + (v == null ? '<span class="muted">' + esc((rep.na[e] && rep.na[e][k]) ? "no result" : "–") + "</span>" : (v === best ? "<b>" + esc(fmt(v, M.digits)) + "</b>" : esc(fmt(v, M.digits)))) + (rec != null ? '<span class="rc">recall ' + fmt(rec, 3) + "</span>" : "") + "</td>";
      });
      h += "</tr>";
    });
    h += "</tbody></table></div>";
    el.innerHTML = h;
  }

  /* -------------------------------------------------------- scoreboard */
  function renderScoreboard(el) {
    var ids = (el.getAttribute("data-scoreboard") || "cloud-10m,cloud-1m,laptop").split(",").filter(function (id) { return R[id]; });
    if (!ids.length) return pending(el);
    var metric = el.getAttribute("data-metric") || "p50";
    var labels = { "cloud-10m": ["10M documents", "DigitalOcean"], "cloud-1m": ["1M documents", "DigitalOcean"], laptop: ["1M documents", "laptop, kind"] };
    var pages = { "cloud-10m": "bench-10m.html", "cloud-1m": "bench-1m.html", laptop: "bench-laptop.html" };
    function draw() {
      var M = METRICS[metric];
      var h = chips("Measure", [["p50", "Median, 1 client"], ["p99", "p99, 1 client"], ["qps4", "q/s, 4 clients"], ["qps16", "q/s, 16 clients"]], metric);
      h += '<div class="places-wrap"><table class="places score"><thead><tr><th scope="col" class="k">kind</th>';
      ids.forEach(function (id) {
        var rep = R[id];
        h += '<th scope="col"><a href="' + pages[id] + '">' + esc(labels[id][0]) + "</a><small>" + esc(labels[id][1]) + " · " + rep.ranked.length + " engines</small></th>";
      });
      h += "</tr></thead><tbody>";
      var kinds = R[ids[0]].kinds;
      var fam = null;
      kinds.forEach(function (k) {
        if (k.fam !== fam) {
          fam = k.fam;
          h += '<tr class="grp"><th colspan="' + (ids.length + 1) + '">' + ({ text: "Full text", cols: "Columns and keys", vec: "Vectors", hyb: "Hybrid" })[fam] + "</th></tr>";
        }
        h += '<tr><th scope="row" class="k">' + esc(k.name) + "</th>";
        ids.forEach(function (id) {
          var rep = R[id], engines = rep.ranked, n = engines.length;
          var pl = placesOf(rep, metric, k.id, engines);
          var p = pl.strata, v = val(rep, metric, "strata", k.id);
          var bestE = null, bestV = null;
          engines.forEach(function (e) { if (pl[e] === 1) { bestE = e; bestV = val(rep, metric, e, k.id); } });
          var tip = "<b>Strata</b> · " + esc(k.name) + "<br>" + (p == null ? "no value" : ord(p) + " of " + n + ": " + esc(fmt(v)) + " " + esc(M.unit)) + (bestE && bestE !== "strata" ? "<br>Best: " + esc(engineName(rep, bestE)) + ", " + esc(fmt(bestV)) + " " + esc(M.unit) : "");
          h += '<td class="' + placeClass(p, n) + '"><span tabindex="0" data-tip="' + esc(tip) + '"><b>' + (p == null ? "–" : ord(p)) + "</b><small>" + (p == null ? "" : esc(fmt(v)) + (M.unit === "ms" ? " ms" : "")) + "</small></span></td>";
        });
        h += "</tr>";
      });
      h += '<tr class="total"><th scope="row" class="k">Overall, summed places</th>';
      ids.forEach(function (id) {
        var rep = R[id], pos = 0;
        rep.rank.forEach(function (r, i) { if (r.e === "strata") pos = i + 1; });
        h += '<td class="' + placeClass(pos, rep.ranked.length) + '"><span><b>' + ord(pos) + "</b><small>of " + rep.ranked.length + "</small></span></td>";
      });
      h += "</tr></tbody></table></div>";
      h += '<div class="legend pl-legend"><span><i class="pl-1"></i>1st</span><span><i class="pl-2"></i>top quarter</span><span><i class="pl-3"></i>middle</span><span><i class="pl-4"></i>lower</span><span><i class="pl-5"></i>last</span><span>Hover or tap a cell for the engine that beat Strata.</span></div>';
      el.innerHTML = h;
      el.querySelectorAll(".chipbtn").forEach(function (b) { b.addEventListener("click", function () { metric = b.getAttribute("data-v"); draw(); }); });
    }
    draw();
  }

  /* ------------------------------------------------------------ writes */
  function renderWrites(el) {
    var rep = R[el.getAttribute("data-writes")];
    if (!rep) return pending(el);
    var es = Object.keys(rep.writes).concat(Object.keys(rep.stream).filter(function (e) { return !rep.writes[e]; }));
    var order = rep.engines.map(function (e) { return e.id; }).filter(function (e) { return es.indexOf(e) >= 0; });
    var cols = [
      ["insert1", "inserts/s, one a request", false, "w"], ["batch16", "inserts/s, 100 a request", false, "w"],
      ["update16", "updates/s", false, "w"],
      ["visible_p50", "searchable after", true, "w", " ms"],
      ["kept", "stream kept up at", false, "s", "/s"], ["flat", "stream flat out", false, "s", "/s"],
      ["again", "written twice after a crash", true, "s"], ["lost", "lost", true, "s"]
    ];
    var h = '<div class="table-wrap"><table class="data wrap-head"><thead><tr><th scope="col">engine</th>';
    cols.forEach(function (c) { h += '<th scope="col" class="num">' + esc(c[1]) + "</th>"; });
    h += "</tr></thead><tbody>";
    var bests = cols.map(function (c) {
      var vs = order.map(function (e) { var src = c[3] === "w" ? rep.writes[e] : rep.stream[e]; return src ? src[c[0]] : null; }).filter(function (v) { return v != null; });
      return vs.length ? (c[2] ? Math.min.apply(null, vs) : Math.max.apply(null, vs)) : null;
    });
    order.forEach(function (e) {
      h += "<tr" + (e === "strata" ? ' class="self"' : "") + '><th scope="row">' + esc(engineName(rep, e)) + "</th>";
      cols.forEach(function (c, i) {
        var src = c[3] === "w" ? rep.writes[e] : rep.stream[e];
        var v = src ? src[c[0]] : null;
        var s = v == null ? "–" : fmt(v) + (c[4] || "");
        h += '<td class="n">' + (v != null && v === bests[i] ? "<b>" + esc(s) + "</b>" : esc(s)) + "</td>";
      });
      h += "</tr>";
    });
    h += "</tbody></table></div>";
    h += '<p class="small muted">Inserts and updates at 16 clients; searchable after is the median from a write to the first search that finds it; streams in documents a second; best in bold.</p>';
    el.innerHTML = h;
  }

  /* -------------------------------------------------------------- load */
  function renderLoad(el) {
    var rep = R[el.getAttribute("data-load")];
    if (!rep) return pending(el);
    var rows = rep.engines.filter(function (e) { return rep.load[e.id]; }).map(function (e) { return { e: e, l: rep.load[e.id] }; });
    rows.sort(function (a, b) { return a.l.s - b.l.s; });
    var h = '<div class="table-wrap"><table class="data"><thead><tr><th scope="col">engine</th><th scope="col" class="num">load</th><th scope="col" class="num">index size</th></tr></thead><tbody>';
    rows.forEach(function (r) {
      var s = r.l.s, t = s >= 3600 ? (s / 3600).toFixed(1) + " h" : s >= 120 ? Math.round(s / 60) + " min" : s + " s";
      h += "<tr" + (r.e.id === "strata" ? ' class="self"' : "") + '><th scope="row">' + esc(r.e.name) + (r.e.id === "strata" ? ' <span class="small muted">built offline</span>' : r.e.lane ? ' <span class="small muted">' + esc(r.e.lane) + "</span>" : "") + '</th><td class="n">' + t + '</td><td class="n">' + (r.l.gb ? fmt(r.l.gb) + " GB" + (r.l.mem ? " in memory" : "") : "–") + "</td></tr>";
    });
    h += "</tbody></table></div>";
    el.innerHTML = h;
  }

  /* -------------------------------------------------------- graph rank */
  function renderGraphRank(el) {
    var rep = R.graph;
    if (!rep) return pending(el);
    var max = rep.rank[rep.rank.length - 1].points;
    var h = '<div class="rankbars">';
    rep.rank.forEach(function (r, i) {
      var self = r.name.indexOf("Strata") === 0;
      h += '<div class="rb-row' + (self ? " self" : "") + '"><span class="rb-pl">' + (i + 1) + '</span><span class="rb-name">' + esc(r.name) + '</span><span class="rb-bar"><i style="width:' + ((r.points / max) * 100).toFixed(1) + '%"></i><b>' + r.points + "</b></span></div>";
    });
    h += "</div>";
    el.innerHTML = h;
  }

  /* ---------------------------------------------------------------- ab */
  function renderAB(el) {
    var rep = R[el.getAttribute("data-ab")];
    if (!rep) return pending(el);
    var h = '<div class="table-wrap"><table class="data"><thead><tr><th scope="col">kind</th><th scope="col" class="num">clients</th><th scope="col" class="num">q/s before</th><th scope="col" class="num">q/s after</th><th scope="col" class="num">change</th><th scope="col" class="num">median before</th><th scope="col" class="num">median after</th></tr></thead><tbody>';
    rep.rows.forEach(function (r) {
      h += '<tr><th scope="row">' + esc(kindName(R["cloud-1m"] || { kinds: [] }, r.kind)) + '</th><td class="n">' + r.clients + '</td><td class="n">' + fmt(r.before) + '</td><td class="n"><b>' + fmt(r.after) + '</b></td><td class="n">' + (r.after >= r.before ? "+" : "−") + Math.abs(Math.round((r.after / r.before - 1) * 100)) + '%</td><td class="n">' + fmt(r.p50_before) + ' ms</td><td class="n">' + fmt(r.p50_after) + " ms</td></tr>";
    });
    h += "</tbody></table></div>";
    el.innerHTML = h;
  }

  /* ---------------------------------------------------------- variants */
  function renderVariants(el) {
    var rep = R[el.getAttribute("data-variants")];
    if (!rep || !rep.variants) return pending(el);
    var h = '<div class="table-wrap"><table class="data"><thead><tr><th scope="col">rule</th><th scope="col">1st</th><th scope="col">2nd</th><th scope="col">3rd</th><th scope="col" class="num">Strata</th></tr></thead><tbody>';
    rep.variants.forEach(function (v) {
      var pos = 0;
      v.rank.forEach(function (r, i) { if (r[0] === "strata") pos = i + 1; });
      h += '<tr><th scope="row">' + esc(v.rule) + (v.kinds ? '<span class="small muted"> (' + esc(v.kinds.map(function (k) { return kindName(rep, k); }).join(", ")) + ")</span>" : "") + "</th>";
      for (var i = 0; i < 3; i++) {
        var r = v.rank[i];
        h += "<td" + (r && r[0] === "strata" ? ' class="self"' : "") + ">" + (r ? esc(engineName(rep, r[0])) + ' <span class="muted">' + esc(v.avg ? fmt(r[1], 2) : String(r[1])) + "</span>" : "") + "</td>";
      }
      h += '<td class="n"><b>' + ord(pos) + "</b></td></tr>";
    });
    h += "</tbody></table></div>";
    el.innerHTML = h;
  }

  /* ----------------------------------------------- overall, as a tile */
  var LABELS = { "cloud-10m": "10M passages · DigitalOcean", "cloud-10m-h2h": "10M · latest main, same nodes", "cloud-1m": "1M passages · DigitalOcean", "cloud-1m-first": "1M · first run", laptop: "1M passages · laptop cluster" };
  var CHIPS = { "cloud-10m": "at 10M documents in the cloud", "cloud-10m-h2h": "at 10M against Elasticsearch and OpenSearch on the same nodes", "cloud-1m": "at 1M in the cloud", "cloud-1m-first": "in the first 1M run", laptop: "on a laptop's cluster" };
  function renderOverall(el) {
    var id = el.getAttribute("data-overall"), rep = R[id], mode = el.getAttribute("data-mode") || "line";
    if (!rep) {
      if (mode === "chip") { el.innerHTML = '<b>Pending</b> ' + esc(CHIPS[id] || id); return; }
      el.innerHTML = mode === "tile" ? '<span class="eyebrow">' + esc(LABELS[id] || id) + '</span><span class="v pend">Pending</span><p>The run has finished; this fills in when its raw results are committed.</p>' : '<span class="pend">Results pending: this fills in when the run\'s raw results are committed.</span>';
      return;
    }
    var pos = 0;
    rep.rank.forEach(function (r, i) { if (r.e === "strata") pos = i + 1; });
    var top = rep.rank.slice(0, 3).map(function (r) { return esc(engineName(rep, r.e)) + " " + r.points; }).join(", ");
    var passes = rep.passes_note || (rep.passes > 1 ? "medians of " + rep.passes + " passes" : "one pass");
    var head = ord(pos) + " of " + rep.ranked.length;
    if (mode === "chip") el.innerHTML = "<b>" + head + "</b> " + esc(CHIPS[id] || LABELS[id] || id);
    else if (mode === "tile") el.innerHTML = '<span class="eyebrow">' + esc(LABELS[id] || id) + '</span><span class="v">' + head + "</span><p>Summed places on " + rep.tests + " tests, " + passes + ": " + top + ".</p>";
    else el.innerHTML = "<b>" + head + "</b> on summed places over " + rep.tests + " tests (" + passes + "): " + top + ".";
  }

  /* ------------------------------------------------------ short ranking */
  // The top few engines by summed places, and Strata wherever it lands.
  function renderRankMini(el) {
    var rep = R[el.getAttribute("data-rank-mini")];
    if (!rep) { el.innerHTML = '<p class="rmini-cap">Results pending.</p>'; return; }
    var top = parseInt(el.getAttribute("data-top") || "5", 10);
    var max = rep.rank[rep.rank.length - 1].points;
    var h = '<ol class="rmini" aria-label="Engines by summed places, fewest points first">';
    rep.rank.forEach(function (r, i) {
      if (i >= top && r.e !== "strata") return;
      var w = Math.max(4, (r.points / max) * 100);
      h += '<li class="' + (r.e === "strata" ? "self" : "") + '"><span class="p">' + (i + 1) + '</span><span>' + esc(engineName(rep, r.e)) + '</span><span class="bar"><i style="width:' + w.toFixed(1) + '%"></i></span><span class="v">' + r.points + "</span></li>";
    });
    h += "</ol>";
    h += '<p class="rmini-cap">Summed places over ' + rep.tests + " tests, fewer points is better. " + rep.ranked.length + " engines ranked.</p>";
    el.innerHTML = h;
  }

  /* ----------------------------------------------- the engines measured */
  function renderEngineNames(el) {
    var seen = {}, names = [];
    el.getAttribute("data-engine-names").split(",").forEach(function (id) {
      var rep = R[id];
      ((rep && rep.engines) || []).forEach(function (e) {
        if (e.id === "strata" || seen[e.name]) return;
        seen[e.name] = 1; names.push(e.name);
      });
    });
    (el.getAttribute("data-also") || "").split(",").forEach(function (n) { n = n.trim(); if (n && !seen[n]) { seen[n] = 1; names.push(n); } });
    el.innerHTML = names.map(function (n) { return "<span>" + esc(n) + "</span>"; }).join("");
  }

  /* ------------------------------------------------------- one number */
  function renderV(el) {
    var p = el.getAttribute("data-num").split(":");
    var rep = R[p[0]];
    var v = rep && val(rep, p[1], p[2], p.slice(3).join(":"));
    el.textContent = v == null ? "–" : fmt(v, METRICS[p[1]] && METRICS[p[1]].digits);
  }

  function pending(el) {
    el.innerHTML = '<div class="note warn"><b>Results pending</b>The raw results of this run are not in the repository yet; this view fills in when they are.</div>';
  }

  function boot() {
    document.querySelectorAll("[data-rank]").forEach(renderRank);
    document.querySelectorAll("[data-places]").forEach(renderPlaces);
    document.querySelectorAll("[data-explorer]").forEach(renderExplorer);
    document.querySelectorAll("[data-pick]").forEach(renderPick);
    document.querySelectorAll("[data-scoreboard]").forEach(renderScoreboard);
    document.querySelectorAll("[data-writes]").forEach(renderWrites);
    document.querySelectorAll("[data-load]").forEach(renderLoad);
    document.querySelectorAll("[data-graph-rank]").forEach(renderGraphRank);
    document.querySelectorAll("[data-ab]").forEach(renderAB);
    document.querySelectorAll("[data-num]").forEach(renderV);
    document.querySelectorAll("[data-overall]").forEach(renderOverall);
    document.querySelectorAll("[data-rank-mini]").forEach(renderRankMini);
    document.querySelectorAll("[data-engine-names]").forEach(renderEngineNames);
    document.querySelectorAll("[data-variants]").forEach(renderVariants);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot); else boot();
})();
